ACPI_STATUS AcpiPsCompleteFinalOp(ACPI_WALK_STATE *WalkState, ACPI_PARSE_OBJECT *Op, ACPI_STATUS Status) {
    ACPI_PARSE_OBJECT *Parent;
    ACPI_PARSE_OBJECT *Next;
    ACPI_OPERAND_OBJECT *Obj;

    if (!WalkState || !Op) {
        return (AE_BAD_PARAMETER);
    }

    if (Status != AE_OK) {
        return (Status);
    }

    if (Op->Asl.Child) {
        return (AE_ALREADY_EXISTS);
    }

    Parent = Op->Common.Parent;
    while (Parent && (Parent->Common.Value.Type != ACPI_PTYPE_1A_OP)) {
        Parent = Parent->Common.Parent;
    }

    if (Parent && (Parent->Common.Value.Type == ACPI_PTYPE_1A_OP)) {
        Next = Parent->Common.Value.Arg;
        if (Next && (Next->Common.Type == ACPI_PTYPE_1A_OP)) {
            Op->Common.Value.Arg = Next->Common.Value.Arg;
        }
    }

    if (WalkState->ParserState.ScopeDepth > 0) {
        WalkState->ParserState.ScopeDepth--;
    }

    return (AE_OK);
}

ACPI_STATUS AcpiPsCompleteFinalOp(ACPI_WALK_STATE *WalkState, ACPI_PARSE_OBJECT *Op, ACPI_STATUS Status)
{
    ACPI_STATUS Status2 = AE_OK;
    ACPI_PARSE_OBJECT *ParentOp;

    if (!WalkState || !Op)
    {
        return (AE_BAD_PARAMETER);
    }

    if (Status != AE_OK)
    {
        return (Status);
    }

    while (Op)
    {
        if (AcpiPsIsAscendingCallbackNeeded(WalkState, Op))
        {
            Status2 = AcpiUtExecuteAscendingCallback(WalkState, Op, Status2);
            if (Status2 != AE_OK)
            {
                return (Status2);
            }
        }

        ParentOp = Op->Common.Parent;
        if (!ParentOp)
        {
            break;
        }

        Op = ParentOp;
    }

    AcpiUtPopScope(WalkState);

    return (Status);
}

ACPI_STATUS AcpiPsCompleteFinalOp(ACPI_WALK_STATE *WalkState, ACPI_PARSE_OBJECT *Op, ACPI_STATUS Status) {
    ACPI_STATUS status = Status;

    if (WalkState && Op) {
        /* Execute any ascending callbacks */
        if (Op->Asl.Callback) {
            status = Op->Asl.Callback(WalkState, Op, Status);
        }

        /* Process the final operation and manage the scope stack */
        if (ACPI_SUCCESS(status)) {
            if (WalkState->Scope) {
                WalkState->Scope = WalkState->Scope->Prev;
            }
        }
    }

    return status;
}

ACPI_STATUS AcpiPsCompleteFinalOp(ACPI_WALK_STATE *WalkState, ACPI_PARSE_OBJECT *Op, ACPI_STATUS Status)
{
    ACPI_PARSE_OBJECT *PrevOp;
    ACPI_NAMESPACE_NODE *Node;

    if (!WalkState || !Op) {
        return (AE_BAD_PARAMETER);
    }

    /* Check for ascending callbacks */
    if (WalkState->MethodCallDepth) {
        WalkState->MethodCallDepth--;
    }

    PrevOp = Op->Common.Value.Obj;
    if (PrevOp && PrevOp->OpType == AML_SCOPE_OP) {
        Node = PrevOp->Value.ScopeNode;
        if (Node) {
            /* Clear the scope stack */
            WalkState->ScopeInfo = Node->ScopeInfo;
            Node->ScopeInfo = NULL;
        }
    }

    /* Complete the final operation */
    if (ACPI_FAILURE(Status)) {
        return (Status);
    }

    return (AE_OK);
}

ACPI_STATUS AcpiPsCompleteOp(ACPI_WALK_STATE *WalkState, ACPI_PARSE_OBJECT *Op, ACPI_STATUS Status)
{
    ACPI_PARSE_OBJECT *ParentOp;

    /* If the Op is NULL, we are done with this branch of the parse tree */
    if (!Op) {
        return (Status);
    }

    /* Get parent operation */
    ParentOp = Op->Common.Parent;

    /* If there is a closing method for this Op, call it now */
    if (Op->OpType >= 0) {
        if (WalkState->DescBasePtr && WalkState->ParserState.NextOp) {
            WalkState->AmlLength = WalkState->ParserState.AmlLength;
            WalkState->Aml = WalkState->ParserState.Aml;
        }

        if (WalkState->MethodDesc) {
            WalkState->DescBasePtr = WalkState->MethodDesc;
        }

        if (Op->OpFlags & AOPOF_RESOLVED) {
            (void)AcpiUtPopScope(WalkState);
        }

        if (WalkState->ArgCount) {
            WalkState->ArgCount--;
        }
    }

    if (ParentOp && (ParentOp->Common.Value.ArgListCount > 0)) {
        ParentOp->Common.Value.ArgListCount--;
    }

    return (Status);
}
